{"command": "python3 << 'PYEOF'
import json, urllib.request, re, time

with open('/home/user/.gitconfig', 'r') as f:
    gitconfig = f.read()
match = re.search(r'x-access-token:([^@]+)@github\.com/ibb142/ivx-holdings-platform', gitconfig)
github_token = match.group(1)
REPO = "ibb142/ivx-holdings-platform"

def gh(path):
    url = f"https://api.github.com/repos/{REPO}/{path}"
    headers = {'Authorization': f'token {github_token}', 'Accept': 'application/vnd.github+json'}
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=15) as resp:
        return json.loads(resp.read().decode())

print("=== CI RE-RUN LATEST STATUS ===")
runs = gh('actions/workflows/ivx-ci.yml/runs?per_page=3&branch=main')
for run in runs['workflow_runs'][:3]:
    print(f"Run {run['run_number']} attempt {run['run_attempt']}: {run['status']} / {run['conclusion']} | updated {run['updated_at']}")
    print(f"  URL: {run['html_url']}")
    if run['status'] == 'completed' and run['conclusion'] == 'failure':
        try:
            jobs = gh(f"actions/runs/{run['id']}/jobs")
            for job in jobs.get('jobs', [])[:5]:
                print(f"    Job '{job['name']}': {job['conclusion']}")
                try:
                    annotations = gh(f"actions/runs/{run['id']}/jobs/{job['id']}/annotations")
                    for a in annotations[:3]:
                        print(f"      {a.get('message', '')[:250]}")
                except: pass
        except: pass
    print()
PYEOF"}
